patch:
diff --git a/proxy.ts b/proxy.ts
index 7921fccb..c1a7a86a 100644
--- a/proxy.ts
+++ b/proxy.ts
@@ -23,6 +23,9 @@ import { PORTAL_ACTIVE_SLUG_HEADER } from "./lib/portal/active-slug-header";
 //    /client/admin is the owner-only surface nested inside it and is checked
 //    FIRST, so a tenant session can never open it.
 //
+// 2.5. /partners gate (always on): requires any valid /client session (same
+//    cookie, same /client/login password check).
+//
 // 3. /lab gate (always on in a deployed build): the nine design-prototype
 //    routes. They carry noindex, which stops Google indexing them but does
 //    NOT stop the sixteen AI crawlers robots.txt names by allowing them - and
@@ -133,6 +136,11 @@ export async function proxy(req: NextRequest) {
     p.startsWith("/client/admin/") ||
     rawLower === "/client/admin" ||
     rawLower.startsWith("/client/admin/");
+  const underPartners =
+    p === "/partners" ||
+    p.startsWith("/partners/") ||
+    rawLower === "/partners" ||
+    rawLower.startsWith("/partners/");
   const underLab =
     p === "/lab" ||
     p.startsWith("/lab/") ||
@@ -219,6 +227,15 @@ export async function proxy(req: NextRequest) {
     else headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
     return NextResponse.next({ request: { headers } });
   }
+  // --- Gate 2a: /partners. Same sol_client session and login as /client (the
+  // password is checked once, at /client/login); no slug is enforced because
+  // /partners names no workspace. ---
+  if (underPartners) {
+    const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
+    const session = cookie ? await verifyClientSessionEdge(cookie) : null;
+    if (!session) return NextResponse.redirect(new URL("/client/login", req.url));
+    return NextResponse.next();
+  }
   // --- Gate 2b: /client-docs/<slug>/* (per-tenant static reference docs) ---
   // A client may only reach a slug their session was granted, so client A can
   // never fetch client B's doc.
